import type { ExtendButtonBase } from '@mui/material/ButtonBase';
import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import IconButton, {
  type IconButtonProps,
  type IconButtonTypeMap,
} from '@mui/material/IconButton';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import { forwardRef, type ElementType } from 'react';
import { iconButtonStyles } from './sv-icon-button.styles.ts';

export type SvIconButtonAppearance = 'default' | 'webinar';
interface SvIconButtonOwnProps {
  appearance?: SvIconButtonAppearance | undefined;
}
export type SvIconButtonProps<C extends ElementType = 'button'> =
  IconButtonProps<C, SvIconButtonOwnProps>;

declare module '@mui/material/styles' {
  interface ComponentsPropsList {
    SvIconButton: SvIconButtonProps;
  }
  interface Components {
    SvIconButton?:
      { defaultProps?: Partial<SvIconButtonProps> | undefined } | undefined;
  }
}

export const SvIconButton = forwardRef<HTMLButtonElement, SvIconButtonProps>(
  function SvIconButton(inProps, ref) {
    const muiDefaults = useDefaultProps<SvIconButtonProps>({
      props: {},
      name: 'MuiIconButton',
    });
    const svDefaults = useDefaultProps<SvIconButtonProps>({
      props: {},
      name: 'SvIconButton',
    });
    const svProps = useDefaultProps({ props: inProps, name: 'SvIconButton' });
    const resolved = useDefaultProps({ props: svProps, name: 'MuiIconButton' });
    const {
      appearance = 'default',
      color = 'default',
      size = 'medium',
      loading = null,
      children,
      className,
      ...props
    } = resolved;
    return (
      <IconButton
        {...props}
        ref={ref}
        color={color}
        size={size}
        loading={loading}
        aria-busy={loading ? true : props['aria-busy']}
        className={clsx(
          'SvIconButton-root',
          `SvIconButton-appearance-${appearance}`,
          className
        )}
        sx={mergeSx(
          (theme) =>
            iconButtonStyles(theme, { appearance, color, size, loading }),
          muiDefaults.sx,
          svDefaults.sx,
          inProps.sx
        )}
      >
        <span className="SvIconButton-icon">{children}</span>
      </IconButton>
    );
  }
) as ExtendButtonBase<IconButtonTypeMap<SvIconButtonOwnProps>>;
